29	import java.time.Duration;
30	
31	public class WindowStoreMaterializer<K, V> extends MaterializedStoreFactory<K, V, WindowStore<Bytes, byte[]>> {
32	
33	    private final Windows<?> windows;
34	    private final EmitStrategy emitStrategy;
35	    private final long retentionPeriod;
36	
37	    public WindowStoreMaterializer(
38	            final MaterializedInternal<K, V, WindowStore<Bytes, byte[]>> materialized,
39	            final Windows<?> windows,
40	            final EmitStrategy emitStrategy
41	    ) {
42	        super(materialized);
43	        this.windows = windows;
44	        this.emitStrategy = emitStrategy;
45	
46	        retentionPeriod = retentionPeriod();
47	
48	        if ((windows.size() + windows.gracePeriodMs()) > retentionPeriod) {
49	            throw new IllegalArgumentException("The retention period of the window store "
50	                    + materialized.storeName() + " must be no smaller than its window size plus the grace period."
51	                    + " Got size=[" + windows.size() + "],"
52	                    + " grace=[" + windows.gracePeriodMs() + "],"
53	                    + " retention=[" + retentionPeriod + "]");
54	        }
55	    }
56	
57	    @Override
58	    public StoreBuilder<?> builder() {
59	        final WindowBytesStoreSupplier supplier = materialized.storeSupplier() == null
60	                ? dslStoreSuppliers().windowStore(new DslWindowParams(
61	                        materialized.storeName(),
62	                        Duration.ofMillis(retentionPeriod),
63	                        Duration.ofMillis(windows.size()),
64	                        false,
65	                        emitStrategy,
66	                        false,
67	                        true
68	                ))
69	                : (WindowBytesStoreSupplier) materialized.storeSupplier();
70	
71	        final StoreBuilder<TimestampedWindowStore<K, V>> builder = Stores.timestampedWindowStoreBuilder(
72	                supplier,
73	                materialized.keySerde(),
74	                materialized.valueSerde()
75	        );
76	
77	        if (materialized.loggingEnabled()) {
78	            builder.withLoggingEnabled(materialized.logConfig());
79	        } else {
80	            builder.withLoggingDisabled();
81	        }
82	
83	        if (materialized.cachingEnabled()) {
84	            builder.withCachingEnabled();
85	        }
86	
87	        return builder;
88	    }
89	
90	    @Override
91	    public final long retentionPeriod() {
92	        return materialized.retention() != null
93	                ? materialized.retention().toMillis()
94	                : windows.size() + windows.gracePeriodMs();
95	    }
96	
97	    @Override
98	    public long historyRetention() {
99	        throw new IllegalStateException(
100	                "historyRetention is not supported when not a versioned store");
101	    }
102	
103	    @Override
104	    public boolean isWindowStore() {
105	        return true;
106	    }
107	
108	    @Override
109	    public boolean isVersionedStore() {
110	        return false;
111	    }
112	}
